/* ---------- LOGO KOALA KIDS (PDF) ---------- */
const LOGO_KK="data:image/png;base64,";
const LOGO_W=32, LOGO_H=14.6;   /* mm, ratio 360x164 conserve */

/* Logo Conseil departemental du Var — utilise uniquement en page 1 du
   support de controle EAJE, a gauche, face au logo Koala Kids. */
const LOGO_VAR="data:image/png;base64,";
const LOGO_VAR_W=30, LOGO_VAR_H=11.4;   /* mm, ratio 360x137 conserve */
function pdfLogoVar(doc,y){
  try{doc.addImage(LOGO_VAR,'PNG',14,y,LOGO_VAR_W,LOGO_VAR_H);}catch(e){console.warn('logo Var PDF',e);}
}

/* Place le logo en haut a droite et renvoie le y de depart du contenu */
function pdfLogo(doc,y){
  try{doc.addImage(LOGO_KK,'PNG',196-LOGO_W,10,LOGO_W,LOGO_H);}catch(e){console.warn('logo PDF',e);}
  return Math.max(y,10+LOGO_H+6);
}

/* ---------- APERCU PDF AVANT TELECHARGEMENT ---------- */
/* Tous les exports passent desormais par pdfSortie() : soit telechargement
   direct (comportement historique), soit affichage dans la visionneuse quand
   l'utilisateur a clique sur « Apercu ». Le document n'est pas ecrit sur le
   disque tant qu'il n'a pas ete demande explicitement. */
let PDF_APERCU=false,PDF_BLOB_URL=null,PDF_SRC=null,PDF_NOM=null;
/* Affiche une source dans la visionneuse. blobALiberer vaut l'URL blob a
   revoquer a la fermeture, ou null pour un fichier deja heberge (bucket assets). */
function pdfAfficher(src,nom,blobALiberer,srcTelechargement,mention){
  pdfLibererBlob();
  PDF_BLOB_URL=blobALiberer||null;
  PDF_SRC=srcTelechargement||src;
  PDF_NOM=nom;
  document.getElementById('pdfNom').textContent=(nom||'')+(mention||'');
  const f=document.getElementById('pdfFrame');
  f.removeAttribute('srcdoc');
  f.src=src;
  document.getElementById('ovPdf').classList.add('on');
}
/* Variante HTML : utilisee pour les .docx convertis. Le contenu est injecte via
   srcdoc pour rester isole du style de l'application. Le bouton Telecharger
   pointe toujours sur le fichier Word d'origine. */
function pdfAfficherHtml(interieur,nom,srcTelechargement){
  /* Le HTML converti est servi via un blob text/html plutot que par srcdoc :
     srcdoc peut etre neutralise par les regles de securite du navigateur. */
  const page='<!DOCTYPE html><meta charset="utf-8"><style>'
    +'body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:1.65;'
    +'color:#2B2740;padding:26px 30px;max-width:820px;margin:0 auto}'
    +'h1,h2,h3{color:#4A3F9F;line-height:1.3}img{max-width:100%;height:auto}'
    +'table{border-collapse:collapse;width:100%;margin:12px 0}'
    +'td,th{border:1px solid #DED8EE;padding:5px 8px;text-align:left;vertical-align:top}'
    +'th{background:#EEECFA}'
    +'h3.feuille{margin:22px 0 6px;font-size:13px;text-transform:uppercase;letter-spacing:.6px}'
    +'.classeur{overflow-x:auto}.classeur table{width:auto;min-width:100%}'
    +'.classeur td,.classeur th{white-space:nowrap}'
    +'table.xl{font-size:12.5px;border-collapse:collapse}'
    +'table.xl td,table.xl th{border:1px solid #D9D2EC;padding:5px 9px;vertical-align:middle}'
    +'table.xl td.num,table.xl th.num{text-align:right;font-variant-numeric:tabular-nums}'
    +'table.xl tr.entete th{position:sticky;top:0;background:#4A3F9F;color:#fff;'
    +'font-weight:700;font-size:11.5px;text-transform:uppercase;letter-spacing:.4px;text-align:left}'
    +'table.xl tbody tr:nth-child(even):not(.entete){background:#FAF8FD}'
    +'table.xl td:empty{background:#fff}</style>'+interieur;
  const url=URL.createObjectURL(new Blob([page],{type:'text/html;charset=utf-8'}));
  pdfAfficher(url,nom,url,srcTelechargement,' \u2014 aper\u00e7u de lecture, mise en page approch\u00e9e');
}
function pdfImprimer(){
  const f=document.getElementById('pdfFrame');
  try{f.contentWindow.focus();f.contentWindow.print();}
  catch(e){toast('Impression impossible ici — utiliser « Ouvrir dans un onglet »');}
}
function pdfSortie(doc,nom){
  if(!PDF_APERCU){doc.save(nom);return;}
  const url=URL.createObjectURL(doc.output('blob'));
  pdfAfficher(url,nom,url);
}
/* Apercu d'un document « a telecharger » : le fichier joint est affiche depuis
   le bucket, sans passer par le disque. Les formats que le navigateur ne sait
   pas rendre (docx, xlsx) sont ouverts dans un onglet. */
const PDF_EXT_TABLEUR=['xlsx','xls','csv','ods'];
/* Rendu d'une feuille de calcul en tableau HTML. sheet_to_html ignore les
   largeurs de colonnes, les cellules fusionnees et les formats de nombre :
   on reconstruit donc la grille a partir de la feuille pour un apercu fidele. */
function feuilleEnTableau(ws){
  const XL=window.XLSX;
  if(!ws||!ws['!ref'])return '<p><i>Feuille vide.</i></p>';
  const r=XL.utils.decode_range(ws['!ref']);
  const couvert={},ancre={};
  (ws['!merges']||[]).forEach(m=>{
    for(let R=m.s.r;R<=m.e.r;R++)for(let C=m.s.c;C<=m.e.c;C++){
      if(R===m.s.r&&C===m.s.c)ancre[R+':'+C]={rs:m.e.r-m.s.r+1,cs:m.e.c-m.s.c+1};
      else couvert[R+':'+C]=1;
    }
  });
  const cols=ws['!cols']||[];
  let html='<table class="xl"><colgroup>';
  for(let C=r.s.c;C<=r.e.c;C++){
    const l=cols[C]&&(cols[C].wch||cols[C].wpx);
    html+='<col'+(l?' style="width:'+Math.round(cols[C].wpx||l*7.6)+'px"':'')+'>';
  }
  html+='</colgroup><tbody>';
  /* La premiere ligne non vide sert d'en-tete si toutes ses cellules sont du texte. */
  const nbCol=r.e.c-r.s.c+1;
  let ligneEntete=-1;
  for(let R=r.s.r;R<=r.e.r&&ligneEntete===-1;R++){
    let n=0,txt=0;
    for(let C=r.s.c;C<=r.e.c;C++){
      if(couvert[R+':'+C])continue;
      const c=ws[XL.utils.encode_cell({r:R,c:C})];
      if(c&&c.v!=null&&String(c.v).trim()!==''){n++;if(c.t==='s')txt++;}
    }
    /* Une vraie ligne d'en-tete remplit la quasi-totalite des colonnes en texte.
       Cela ecarte les lignes de titre ou de contexte du haut de feuille. */
    if(n>=3&&txt===n&&n>=Math.ceil(nbCol*0.7))ligneEntete=R;
  }
  for(let R=r.s.r;R<=r.e.r;R++){
    let tds='';
    for(let C=r.s.c;C<=r.e.c;C++){
      if(couvert[R+':'+C])continue;
      const c=ws[XL.utils.encode_cell({r:R,c:C})];
      let v=c?(c.w!=null?c.w:(c.v!=null?String(c.v):'')):'';
      /* SheetJS formate toujours avec un point decimal : on repasse a la virgule
         pour les nombres simples, sans toucher aux dates ni aux milliers. */
      if(c&&c.t==='n'&&/^-?\d+\.\d+$/.test(v))v=v.replace('.',',');
      const a=ancre[R+':'+C];
      const attrs=(a?' rowspan="'+a.rs+'" colspan="'+a.cs+'"':'')
                 +(c&&c.t==='n'?' class="num"':'');
      tds+=(R===ligneEntete?'<th'+attrs+'>':'<td'+attrs+'>')
          +esc(v).replace(/\n/g,'<br>')
          +(R===ligneEntete?'</th>':'</td>');
    }
    html+='<tr'+(R===ligneEntete?' class="entete"':'')+'>'+tds+'</tr>';
  }
  return html+'</tbody></table>';
}
const PDF_MIMES={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',
  gif:'image/gif',webp:'image/webp',svg:'image/svg+xml',txt:'text/plain'};
async function apercuFichier(id){
  const d=DOCS.find(x=>x.id===id);
  if(!d||!d.fichier_url)return toast('Aucun fichier joint');
  const nom=d.fichier_nom||d.titre||'document';
  const ext=(String(d.fichier_url).split('?')[0].split('.').pop()||'').toLowerCase();
  const mime=PDF_MIMES[ext];
  /* Word moderne : conversion en HTML par mammoth, lisible sans telechargement. */
  if(ext==='docx'&&window.mammoth){
    toast('Conversion du document\u2026');
    try{
      const r=await fetch(d.fichier_url);
      if(!r.ok)throw new Error('HTTP '+r.status);
      const res=await window.mammoth.convertToHtml({arrayBuffer:await r.arrayBuffer()});
      pdfAfficherHtml((res.value||'<p><i>Document vide.</i></p>')+await sdBlocSignature(d),nom,d.fichier_url);
    }catch(e){
      console.error('apercuFichier docx',e);
      toast('Aper\u00e7u impossible : '+(e&&e.message?e.message:e));
    }
    return;
  }
  /* Classeurs : SheetJS lit xlsx, xls (ancien format binaire), csv et ods.
     Chaque feuille devient un tableau HTML. */
  if(PDF_EXT_TABLEUR.indexOf(ext)!==-1){
    if(!window.XLSX)return toast('Librairie tableur non charg\u00e9e \u2014 recharger la page');
    toast('Conversion du classeur\u2026');
    try{
      const r=await fetch(d.fichier_url);
      if(!r.ok)throw new Error('HTTP '+r.status);
      const wb=window.XLSX.read(new Uint8Array(await r.arrayBuffer()),{type:'array',cellStyles:true});
      const noms=(wb&&wb.SheetNames)||[];
      /* Une feuille illisible (graphique, feuille protegee, macro) ne doit pas
         faire echouer tout l'apercu : chacune est traitee isolement. */
      let html='';
      noms.forEach(n=>{
        const ws=wb.Sheets&&wb.Sheets[n];
        if(!ws)return;
        let t;
        try{t=feuilleEnTableau(ws);}
        catch(err){console.warn('feuille illisible',n,err);t='<p><i>Feuille illisible.</i></p>';}
        html+=(noms.length>1?'<h3 class="feuille">'+esc(n)+'</h3>':'')
             +'<div class="classeur">'+t+'</div>';
      });
      pdfAfficherHtml(html||'<p><i>Classeur vide.</i></p>',nom,d.fichier_url);
    }catch(e){
      console.error('apercuFichier tableur',e);
      toast('Aper\u00e7u impossible : '+(e&&e.message?e.message:e));
    }
    return;
  }
  if(!mime){
    window.open(d.fichier_url,'_blank','noopener');
    toast('Format '+(ext||'inconnu')+' non affichable \u2014 ouverture dans un onglet');
    return;
  }
  /* On telecharge le fichier en memoire et on impose son type MIME : sans cela un
     en-tete Content-Disposition: attachment cote bucket declenche un
     telechargement au lieu de l'affichage, meme dans une iframe. */
  toast('Chargement de l\u2019aper\u00e7u\u2026');
  try{
    const r=await fetch(d.fichier_url);
    if(!r.ok)throw new Error('HTTP '+r.status);
    let b=await r.blob();
    if(b.type!==mime)b=new Blob([b],{type:mime});
    const url=URL.createObjectURL(b);
    pdfAfficher(url,nom,url);
  }catch(e){
    console.error('apercuFichier',e);
    window.open(d.fichier_url,'_blank','noopener');
    toast('Aper\u00e7u indisponible \u2014 ouverture dans un onglet');
  }
}
function pdfLibererBlob(){
  if(PDF_BLOB_URL){try{URL.revokeObjectURL(PDF_BLOB_URL);}catch(e){}PDF_BLOB_URL=null;}
}
async function apercuPdf(){
  const btn=document.getElementById('btnApercu');
  PDF_APERCU=true;
  try{
    if(btn)btn.disabled=true;
    const ok=await exportFillPdf();
    if(!ok)toast('Aper\u00e7u impossible');
  }catch(e){
    console.error('apercuPdf',e);
    toast('Erreur : '+(e&&e.message?e.message:'aper\u00e7u impossible'));
  }finally{
    PDF_APERCU=false;
    if(btn)btn.disabled=false;
  }
}
function pdfTelecharger(){
  if(!PDF_SRC)return;
  const a=document.createElement('a');
  a.href=PDF_SRC;a.download=PDF_NOM||'document.pdf';
  a.target='_blank';a.rel='noopener';
  document.body.appendChild(a);a.click();a.remove();
}
function pdfOnglet(){
  if(!PDF_SRC)return;
  window.open(PDF_SRC,'_blank','noopener');
}
function pdfFermer(){
  close_('ovPdf');
  const f=document.getElementById('pdfFrame');
  if(f){f.removeAttribute('srcdoc');f.src='about:blank';}
  pdfLibererBlob();
  PDF_SRC=null;PDF_NOM=null;
}

/* ---------- EXPORT PDF EN TABLEAU (documents de reference) ---------- */
/* Les libelles de la forme « Groupe — Attribut » sont recomposes en tableau :
   une ligne par groupe (une creche), une colonne par attribut. Les champs sans
   separateur (mail commun, date de mise a jour) sont repris sous le tableau.
   Aucun nom de creche n'est code en dur : tout vient de schema_champs. */
const PDF_SEP=' \u2014 ';
function pdfMatrice(){
  const champs=(fillDoc&&fillDoc.schema_champs)||[];
  const groupes=[],attrs=[],cell={},libres=[];
  champs.forEach(c=>{
    const el=document.getElementById('ff_'+c.key);
    let v=el?(c.type==='checkbox'?(el.checked?'Oui':'Non'):el.value):'';
    if(c.type==='date'&&v){const d=new Date(v);if(!isNaN(d))v=d.toLocaleDateString('fr-FR');}
    const lab=String(c.label||'');
    const i=lab.indexOf(PDF_SEP);
    if(i===-1){libres.push({label:lab,valeur:v});return;}
    const g=lab.slice(0,i).trim(),a=lab.slice(i+PDF_SEP.length).trim();
    if(groupes.indexOf(g)===-1)groupes.push(g);
    if(attrs.indexOf(a)===-1)attrs.push(a);
    cell[g+'\u0000'+a]=v;
  });
  return{groupes,attrs,cell,libres};
}
function pdfMatriceApplicable(m){return m.groupes.length>=2&&m.attrs.length>=2;}

function exportMatricePdf(){
  const m=pdfMatrice();
  const{jsPDF}=window.jspdf;
  const doc=new jsPDF({orientation:'landscape'});
  const PW=297,PH=210,ML=10,W=PW-2*ML,PAD=2,LH=3.6,BAS=PH-14;
  const w0=Math.max(26,Math.min(38,W*0.13));
  const wa=(W-w0)/m.attrs.length;
  const widths=[w0].concat(m.attrs.map(()=>wa));
  const xs=[];let x=ML;widths.forEach(w=>{xs.push(x);x+=w;});
  const wrap=(t,w,size)=>{doc.setFontSize(size);return doc.splitTextToSize(String(t==null?'':t),w-2*PAD);};
  let y=0;

  function bandeau(){
    try{doc.addImage(LOGO_KK,'PNG',PW-ML-LOGO_W,8,LOGO_W,LOGO_H);}catch(e){console.warn('logo PDF',e);}
    y=14+LOGO_H;
    doc.setTextColor(74,63,159);doc.setFontSize(15);doc.setFont(undefined,'bold');
    doc.text(String(fillDoc.titre||''),ML,y);
    doc.setTextColor(30);y+=8;
  }
  function entete(){
    const cells=[''].concat(m.attrs).map((t,i)=>wrap(t,widths[i],7.5));
    const h=Math.max.apply(null,cells.map(l=>l.length))*LH+2*PAD;
    doc.setFillColor(74,63,159);doc.rect(ML,y,W,h,'F');
    doc.setTextColor(255);doc.setFont(undefined,'bold');doc.setFontSize(7.5);
    cells.forEach((l,i)=>doc.text(l,xs[i]+PAD,y+PAD+2.7));
    doc.setTextColor(30);doc.setFont(undefined,'normal');
    y+=h;
  }
  bandeau();entete();

  m.groupes.forEach((g,idx)=>{
    const cells=[wrap(g,widths[0],8)].concat(m.attrs.map((a,i)=>wrap(m.cell[g+'\u0000'+a]||'\u2014',widths[i+1],7.5)));
    const h=Math.max.apply(null,cells.map(l=>l.length))*LH+2*PAD;
    if(y+h>BAS){doc.addPage();bandeau();entete();}
    if(idx%2===1){doc.setFillColor(250,248,253);doc.rect(ML,y,W,h,'F');}
    doc.setDrawColor(222,216,238);
    doc.rect(ML,y,W,h);
    xs.slice(1).forEach(xx=>doc.line(xx,y,xx,y+h));
    cells.forEach((l,i)=>{
      doc.setFont(undefined,i===0?'bold':'normal');
      doc.setFontSize(i===0?8:7.5);
      doc.setTextColor.apply(doc,i===0?[74,63,159]:[30,30,30]);
      doc.text(l,xs[i]+PAD,y+PAD+2.7);
    });
    doc.setTextColor(30);doc.setFont(undefined,'normal');
    y+=h;
  });

  y+=7;doc.setFontSize(8.5);
  m.libres.forEach(f=>{
    if(y>BAS){doc.addPage();bandeau();}
    doc.setFont(undefined,'bold');doc.text(f.label+' :',ML,y);
    doc.setFont(undefined,'normal');doc.text(String(f.valeur||'\u2014'),ML+78,y);
    y+=5.5;
  });

  pdfSortie(doc,slug(fillDoc.titre)+'.pdf');
  return true;
}

async function exportFillPdf(mode){
  const{jsPDF}=window.jspdf;const doc=new jsPDF();
  const tpl=TPL[fillDoc.template_key];
  if(tpl){
    if(tpl.pdf)return tpl.pdf(doc,mode);
    return exportTplPdf(doc,tpl,mode);
  }
  /* Document de reference dont les libelles sont structures « Groupe — Attribut » :
     rendu en tableau paysage plutot qu'en liste champ par champ. */
  if(fillDoc.doc_reference&&pdfMatriceApplicable(pdfMatrice()))return exportMatricePdf();
  let y=pdfLogo(doc,18);
  doc.setFontSize(15);doc.text(fillDoc.titre,14,y);
  doc.setFontSize(10);y+=12;
  (fillDoc.schema_champs||[]).forEach(c=>{
    const el=document.getElementById('ff_'+c.key);
    let v=el?(c.type==='checkbox'?(el.checked?'Oui':'Non'):el.value):'';
    doc.setFont(undefined,'bold');doc.text(c.label+' :',14,y);
    doc.setFont(undefined,'normal');
    const lines=doc.splitTextToSize(String(v||'—'),176);
    doc.text(lines,14,y+6);y+=10+lines.length*5;
    if(y>270){doc.addPage();y=pdfLogo(doc,20);}
  });
  pdfSortie(doc,slug(fillDoc.titre)+'.pdf');
  return true;
}

function exportTplPdf(doc,tpl,mode){
  const g=id=>{const e=document.getElementById('ff_'+id);return e?e.value:'';};
  const rf=()=>{const r=document.querySelector('input[name=ff_fonction]:checked');return r?r.value:'';};
  const W=182;let y=pdfLogo(doc,20);
  const need=h=>{if(y+h>278){doc.addPage();y=pdfLogo(doc,20);}};
  const H=t=>{need(14);doc.setFillColor(74,63,159);doc.rect(14,y-5,W,8,'F');
    doc.setTextColor(255);doc.setFontSize(10);doc.setFont(undefined,'bold');
    doc.text(t.toUpperCase(),16,y);doc.setTextColor(30);y+=12;};
  const L=(lab,val)=>{const lines=doc.splitTextToSize(String(val||'—'),W);
    need(8+lines.length*5);
    doc.setFontSize(9);doc.setFont(undefined,'bold');doc.text(lab,14,y);y+=5;
    doc.setFontSize(10);doc.setFont(undefined,'normal');doc.text(lines,14,y);y+=lines.length*5+5;};

  doc.setFontSize(17);doc.setFont(undefined,'bold');doc.text('ENTRETIEN ANNUEL',14,y);y+=12;

  H("Personne en charge de l'entretien");
  L('Nom',g('rh_nom'));L('Fonction',g('rh_fonction'));
  L("Date de l'entretien",g('rh_date')?new Date(g('rh_date')).toLocaleDateString('fr-FR'):'—');

  H('Salarié(e)');
  L('Nom / Prénom',g('sal_nom'));L('Crèche',g('sal_creche'));
  L('Fonction',rf()==='Autre'?(g('fonction_autre')||'Autre'):rf());

  H("Bilan de l'année");
  L('Aspects positifs, réussites, missions privilégiées',g('b_positif'));
  L('Aspects négatifs, difficultés, manques',g('b_negatif'));
  L("Le poste a-t-il répondu à vos attentes ?",g('b_attentes'));

  H('Année en cours');
  L('Projets professionnels',g('a_projets'));
  L('Objectifs et attentes',g('a_objectifs'));

  H("Synthèse et objectifs de l'année");
  L('',g('synthese'));

  H('Signatures');
  L('Date',g('sig_date')?new Date(g('sig_date')).toLocaleDateString('fr-FR'):'—');
  need(48);
  const put=(role,lab,x)=>{
    doc.setFontSize(9);doc.setFont(undefined,'bold');doc.text(lab,x,y);
    doc.setDrawColor(200);doc.rect(x,y+3,84,32);
    if(SIGS[role]){try{doc.addImage(SIGS[role],'PNG',x+2,y+5,80,28);}catch(e){}}
  };
  put('responsable',"Personne en charge",14);
  put('salarie','Salarié(e)',110);
  y+=40;

  pdfSortie(doc,slug(fillDoc.titre)+'_'+slug(g('sal_nom')||'')+'.pdf');
  return true;
}

/* ---------- EDITION PDF PUIS REINITIALISATION ---------- */
/* Genere le PDF, supprime la reponse en base et remet le formulaire a vierge.
   Aucune donnee n'est conservee dans l'application apres l'edition. */
async function editPdfAndReset(){
  const btn=document.getElementById('btnPdfReset');
  try{
    if(!fillDoc)return;

    /* Document de reference : on exporte et on enregistre, sans rien supprimer. */
    if(fillDoc.doc_reference){
      if(btn)btn.disabled=true;
      const okRef=await exportFillPdf();
      if(!okRef)throw new Error('génération PDF impossible');
      /* saveFill() referme la modale : on rouvre la meme reponse pour que le
         formulaire reste affiche, avec les valeurs desormais enregistrees. */
      const repId=fillRep&&fillRep.id;
      await saveFill();
      toast('PDF exporté — document conservé');
      if(repId)await openFill(fillDoc.id,repId);
      return;
    }

    /* Document d'etablissement (controle EAJE, CERFA) : une grille d'auto-controle
       reglementaire est une piece d'archive. On exporte, on enregistre, et on ne
       supprime RIEN — l'ancien comportement « editer puis vider » effacait la
       fiche en base sans possibilite de retour (perte constatee le 08/09/2026). */
    if(docEstEtablissement()){
      if(btn)btn.disabled=true;
      const okEtab=await exportFillPdf();
      if(!okEtab)throw new Error('génération PDF impossible');
      await saveFill(true);   /* silencieux : n'efface pas et ne ferme pas la modale */
      toast(SAVE_KO?SAVE_KO:'PDF exporté — fiche conservée');
      return;
    }

    // Contexte « dossier enfant » : un enfant est sélectionné, ou on vient de la fiche enfant.
    // Dans ce cas on GÉNÈRE le PDF et on CONSERVE le document (pas d'effacement).
    const enfantSel=(document.getElementById('fillEnfant')||{}).value||'';
    const contexteEnfant=(!!enfantSel || !!RETURN_ENFANT_ID) && !docConcerneSalarie();

    if(contexteEnfant){
      if(btn)btn.disabled=true;
      // générer le PDF pendant que le formulaire est affiché (les champs sont lus dans le DOM)
      const ok=await exportFillPdf();
      if(!ok)throw new Error('génération PDF impossible');
      // puis enregistrer pour garantir un document à jour et rattaché à l'enfant (statut, signatures)
      await saveFill();
      toast('PDF généré — document conservé dans le dossier enfant');
      return;
    }

    // Comportement historique (documents sans enfant, ex. entretien annuel) : générer puis effacer.
    if(!confirm("Éditer le PDF puis vider le formulaire ?\n\nLe document sera téléchargé. Aucune donnée ne sera conservée dans l'application."))return;
    if(btn)btn.disabled=true;

    const ok=await exportFillPdf();
    if(!ok)throw new Error('génération PDF impossible');

    /* suppression de la reponse eventuellement enregistree */
    if(fillRep&&fillRep.id){
      const{error}=await sb.from('documents_reponses').delete().eq('id',fillRep.id);
      if(error)console.warn('suppression réponse',error);
    }
    fillRep=null;

    resetFillForm();
    toast('PDF édité — formulaire réinitialisé');
  }catch(e){
    console.error('editPdfAndReset',e);
    toast('Erreur : '+(e&&e.message?e.message:'édition impossible'));
  }finally{
    if(btn)btn.disabled=false;
  }
}

/* Remet la modale de remplissage a l'etat vierge, sans rouvrir de reponse existante */
function resetFillForm(){
  Object.keys(SIGS).forEach(k=>delete SIGS[k]);
  const _st=document.getElementById('fillStatut');
  if(_st)_st.value='prepare';
  fillStatutManuel=false;
  const tpl=TPL[fillDoc.template_key];
  if(tpl){
    const v={};tpl.fields.forEach(f=>v[f]='');
    document.getElementById('fillArea').innerHTML=tpl.html(v);
    if(tpl.mount)tpl.mount();else ['responsable','salarie'].forEach(mountSig);
  }else{
    document.getElementById('fillArea').innerHTML=(fillDoc.schema_champs||[]).map(c=>{
      let inp;
      if(c.type==='textarea')inp=`<textarea id="ff_${c.key}" rows="3"></textarea>`;
      else if(c.type==='checkbox')inp=`<input type="checkbox" id="ff_${c.key}" style="width:auto">`;
      else inp=`<input type="${c.type}" id="ff_${c.key}" value="">`;
      return `<div class="f"><label>${esc(c.label)}</label>${inp}</div>`;
    }).join('')||'<p style="color:var(--muted);font-size:13px">Ce document n\'a pas encore de champs configurés.</p>';
  }
  document.getElementById('fillState').textContent='Nouvelle saisie';
}

