/* ---------- ENCODAGE PDF ----------
   Les polices standard de jsPDF (Helvetica) n'encodent que le Latin-1 plus
   quelques signes WinAnsi. Un seul caractere hors de ce jeu (>=, <=, fleches...)
   fait basculer TOUTE la chaine en UTF-16 : la ligne s'affiche alors espacee et
   illisible. On substitue donc ces caracteres juste avant l'ecriture. */
const PDF_WINANSI_EXTRA='\u20AC\u201A\u0192\u201E\u2026\u2020\u2021\u02C6\u2030\u0160\u2039\u0152\u017D\u2018\u2019\u201C\u201D\u2022\u2013\u2014\u02DC\u2122\u0161\u203A\u0153\u017E\u0178';
const PDF_SUBST={'\u2265':'>=','\u2264':'<=','\u2260':'\u2260','\u2248':'~','\u2192':'->','\u21D2':'=>','\u00A0':' ','\u202F':' ','\u2044':'/'};
function pdfSafe(v){
  let s=String(v==null?'':v).replace(/[\u2265\u2264\u2248\u2192\u21D2\u00A0\u202F\u2044]/g,c=>PDF_SUBST[c]);
  return s.replace(/[^\u0000-\u00FF]/g,c=>PDF_WINANSI_EXTRA.indexOf(c)>=0?c:' ');
}

/* ---------- TABLEAUX PDF (helper commun aux fiches) ---------- */
function pdfGrid(doc,x,y,widths,rows,opt){
  opt=opt||{};
  const fs=opt.fs||9, lh=4.2;
  rows.forEach(r=>{
    const cells=r.cells||r, head=!!r.head;
    doc.setFontSize(fs);
    doc.setFont(undefined,head?'bold':'normal');
    const wrapped=cells.map((c,i)=>doc.splitTextToSize(pdfSafe(c),widths[i]-4));
    const h=Math.max(opt.minH||8, Math.max.apply(null,wrapped.map(w=>w.length))*lh+4);
    if(y+h>280){doc.addPage();y=pdfLogo(doc,20);}
    let cx=x;
    cells.forEach((c,i)=>{
      if(head){doc.setFillColor(238,237,248);doc.rect(cx,y,widths[i],h,'F');}
      doc.setDrawColor(150);doc.rect(cx,y,widths[i],h);
      doc.setFont(undefined,head?'bold':'normal');
      if(head)doc.text(wrapped[i],cx+widths[i]/2,y+5.5,{align:'center'});
      else doc.text(wrapped[i],cx+2,y+5.5);
      cx+=widths[i];
    });
    y+=h;
  });
  return y;
}

